import axios from "axios";
import { API_URL, isBackendLocalhost } from "../config/appConfig";

const axiosService = axios.create({
  baseURL: API_URL, // Full URL with /api/v1: https://2.24.128.170:4006/api/v1
});

// Detect if running in Electron
const isElectron = () => {
  return (
    typeof window !== 'undefined' &&
    (window.electron?.isElectron === true || 
     window.navigator?.userAgent?.includes('Electron') ||
     (window.process && window.process.type === 'renderer') ||
     window.location.protocol === 'file:')
  );
};

// Use the centralized function from appConfig

// Request interceptor: Add Authorization header only when backend is localhost
axiosService.interceptors.request.use(
  (config) => {
    // Only use localStorage/Authorization header when:
    // 1. Backend is localhost (development)
    // 2. Frontend is also localhost (development)
    // This allows local development to work without cookies
    // For production backend (https://2.24.128.170:4006), use cookies as normal
    if (isBackendLocalhost()) {
      const token = localStorage.getItem('jwttoken') || localStorage.getItem('token');
      if (token) {
        // Set both lowercase and capitalized to ensure compatibility
        config.headers.Authorization = `Bearer ${token}`;
        config.headers.authorization = `Bearer ${token}`; // Express normalizes to lowercase
        console.log('🔐 [Localhost] Token added to Authorization header:', {
          url: config.url,
          method: config.method,
          tokenPreview: token.substring(0, 20) + '...',
          headerSet: !!config.headers.Authorization
        });
      } else {
        console.warn('⚠️ [Localhost] No token found in localStorage for request:', config.url);
      }
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor: Store token from login responses only when backend is localhost
axiosService.interceptors.response.use(
  (response) => {
    // Store token in localStorage only when backend is localhost
    // For production backend, cookies handle authentication
    if (isBackendLocalhost() && response.data?.token) {
      let token = null;
      if (typeof response.data.token === 'string') {
        token = response.data.token;
      } else if (response.data.token?.token) {
        token = response.data.token.token;
      } else if (response.data.token && typeof response.data.token === 'object') {
        // Fallback: try to get token from nested object
        token = response.data.token;
      }
      if (token) {
        localStorage.setItem('jwttoken', token);
        console.log('🔐 [Localhost] Token stored in localStorage');
      }
    }
    return response;
  },
  (error) => {
    return Promise.reject(error);
  }
);


// Endpoint: It is a specific location within API that accepts data and send it back

// Helper: Get credentials setting based on environment
// For localhost backend: Don't use credentials (we use Authorization header instead of cookies)
// For production backend: Use credentials (needed for cookies)
const getCredentialsConfig = () => {
  if (isBackendLocalhost()) {
    return {
      withCredentials: false, // Localhost uses Authorization header, not cookies
      credentials: "omit"
    };
  }
  return {
    withCredentials: true, // Production backend needs this for cookies
    credentials: "include"
  };
};

export const getApi = async (endpoint) => {
  try {
    const credentialsConfig = getCredentialsConfig();
    const response = await axiosService.get(endpoint, {
      ...credentialsConfig,
      headers: { "Content-Type": "application/json" },
    });

    return response.data;
  } catch (error) {
    return (
      error?.response?.data || {
        success: false,
        msg: error?.message,
      }
    );
  }
};
export const getBlobApi = async (endpoint, filters = {}) => {
  try {
    const credentialsConfig = getCredentialsConfig();
    const response = await axiosService.get(endpoint, {
      params: filters,
      responseType: 'blob',
      ...credentialsConfig,
      headers: {
        'Accept': 'text/csv'
      },
    });

    // Return the full response, not just response.data
    return response;
  } catch (error) {
    return (
      error?.response?.data || {
        success: false,
        msg: error?.message,
      }
    );
  }
};
